    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The research question for this review was ' Are there English-language publications in peer-reviewed scientific journals describing how models have been used to allocate resources for malaria interventions in limited resource settings?' The main aim of this review was to identify and characterize models for malaria control optimization for resource allocation in malaria control and elimination settings and to identify their strengths and limitations.",
      "reason": "The review explicitly states both a research question and the main aim/objective, also echoed in the abstract ('This systematic review aimed to identify and characterise models for malaria control optimization...')."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_6",
      "quote": "The main aim of this review was to identify and characterize models for malaria control optimization for resource allocation in malaria control and elimination settings and to identify their strengths and limitations.",
      "reason": "This is a review of optimization models for resource allocation, not a review of intervention effects comparing interventions; no PICO-formatted planned comparisons are reported and the framework does not apply."
    }
  ],
  "confidence": 90
}

